function completed(id){try{return JSON.parse(localStorage.getItem('listening-'+id+'-history')||'[]').some(x=>x.completed)}catch{return false}}
function coverCredit(c){return c?.credit&&c?.source&&c?.licenseUrl?`<p class="notice cover-credit">Photo: <a href="${esc(c.source)}" target="_blank" rel="noopener">${esc(c.credit)}</a> · <a href="${esc(c.licenseUrl)}" target="_blank" rel="noopener">${esc(c.license)}</a></p>`:''}
let DATA=[],CATALOG=[];let part=0,limit=15,selected=[];const $=s=>document.querySelector(s),esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const colors=['#3e4d3b','#3b284a','#8b492d','#263d50','#68614b','#3b5255'];let shown=[];function render(){let q=$('#search').value.toLocaleLowerCase();let arr=DATA.filter(d=>(!part||d.part===part)&&d.title.toLocaleLowerCase().includes(q));arr.sort((a,b)=>a.title.localeCompare(b.title,'en',{sensitivity:'base',numeric:true}));$('#count').textContent=arr.length+' bài nghe'+(part?' · Part '+part:'');shown=arr.slice(0,limit);let cols=innerWidth<=560?2:innerWidth<=900?3:5;$('#books').innerHTML='';for(let i=0;i<shown.length;i+=cols){let shelf=document.createElement('div');shelf.className='shelf';shelf.innerHTML=shown.slice(i,i+cols).map((d,j)=>`<button class="book" style="--color:${colors[(i+j)%colors.length]}" data-id="${esc(d.id)}" aria-label="Xem ${esc(d.title)}"><span class="spine"><span>${esc(d.title)}</span></span><span class="book-top"></span><span class="book-bottom"></span><span class="book-edge"></span><span class="front">${d.image?`<img src="${d.image}" alt="" loading="lazy">`:''}<span class="shade"></span><span class="booktext"><span class="part">Part ${d.part}</span><h2>${esc(d.title)}</h2><span class="types">${d.types.map(esc).join('<br>')}</span></span></span></button>`).join('');$('#books').append(shelf)}if(!arr.length)$('#books').innerHTML='<div class="empty">Không tìm thấy bài nghe. Hãy thử tên khác.</div>';$('#more').hidden=arr.length<=limit;document.querySelectorAll('.book').forEach(b=>b.onclick=()=>openLesson(b.dataset.id))}function openLesson(id){let d=DATA.find(x=>x.id===id);$('#detail').innerHTML=`<div class="detail">${d.image?`<img src="${d.image}" alt="${esc(d.cover?.alt||'')}">`:''}<div><span class="part">Part ${d.part} · ${d.count} câu</span><h2>${esc(d.title)}</h2><p>${d.types.map(esc).join('<br>')}</p><p>${completed(d.id)?'Đã làm':'Chưa làm'}</p><div class="actions"><a class="button primary" href="${esc(d.url)}" target="_blank" rel="noopener">Vào làm bài ↗</a></div></div></div>${coverCredit(d.cover)}`;$('#lesson').showModal()}document.querySelectorAll('[data-part]').forEach(b=>b.onclick=()=>{part=+b.dataset.part;limit=15;document.querySelectorAll('[data-part]').forEach(x=>x.classList.toggle('active',x===b));render()});$('#search').oninput=()=>{limit=15;render()};$('#more').onclick=()=>{limit+=15;render()};document.querySelectorAll('dialog .close').forEach(b=>b.onclick=()=>b.closest('dialog').close());document.querySelectorAll('dialog').forEach(d=>d.addEventListener('click',e=>{if(e.target===d){let r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close()}}));let prevCols=0;window.addEventListener('resize',()=>{let c=innerWidth<=560?2:innerWidth<=900?3:5;if(c!==prevCols){prevCols=c;render()}});async function boot(){try{const response=await fetch('listening-catalog.json',{cache:'no-cache'});if(!response.ok)throw Error();DATA=await response.json();$('#load-status').textContent='';render()}catch{$('#load-status').textContent='Không tải được kho bài nghe. Vui lòng tải lại trang.'}}boot();